/**
 * Customer logos together with the key numbers: logos above the numbers, or beside them. Axes: layout (above,
 * beside), logos (name, icon), tone, density.
 */
import { type ReactNode } from "react";
import { Grid, Group, Stack, Text } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { EmptyState } from "../components/empty-state";
import { SectionFrame } from "../components/section-frame";
import type { Logo } from "./logo-cloud.types";
import type { Stat } from "./stats-band.types";

export type ProofBandProps = {
  id: string;
  title: string;
  logos: Logo[];
  empty?: string;
  stats: Stat[];
  layout?: "above" | "beside";
  logoStyle?: "name" | "icon";
  tone?: "default" | "muted";
  density?: "default" | "compact";
  landmarkLabel?: string;
};

export function ProofBand({
  id,
  title,
  logos,
  empty = "",
  stats,
  layout = "above",
  logoStyle = "name",
  tone = "default",
  density = "default",
  landmarkLabel,
}: ProofBandProps) {
  return (
    <SectionFrame id={id} title={title} tone={tone} density={density} align="center" landmarkLabel={landmarkLabel}>
      {((logos?.length ?? 0) === 0) ? (
        <EmptyState icon="building-2" title={empty} />
      ) : (
        <Grid cols={(((layout as string) === "beside") ? "1-2" : "1")} className="items-center gap-8">
          <Group gap="6" justify="center" className="flex-wrap text-muted-foreground" data-slot="logos">
            {(logos ?? []).map((logo) => (
              <Group key={logo.id} gap="2" align="center" data-slot="logo">
                <LucideIcon name={logo.icon} size={24} />
                <Text size="sm" weight="semibold" className={(((logoStyle as string) === "icon") ? "sr-only" : "")}>
                  {logo.name}
                </Text>
              </Group>
            ))}
          </Group>
          <Grid cols={(((layout as string) === "beside") ? "2" : "1-4")} className="gap-6 text-center" data-slot="stats">
            {(stats ?? []).map((stat) => (
              <Stack key={stat.id} gap="0" align="center" data-slot="stat">
                <Text size="4xl" weight="bold">
                  {stat.value}
                </Text>
                <Text size="sm" className="text-muted-foreground">
                  {stat.label}
                </Text>
              </Stack>
            ))}
          </Grid>
        </Grid>
      )}
    </SectionFrame>
  );
}
